def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    total = sum(values)
    average = total / len(values)
    return {
        "value": average,
        "trace": {
            "values": values,
            "total": total,
            "count": len(values),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
